import gzip, glob, os
import pandas as pd, numpy as np
from collections import Counter

samples = ['RS01', 'RS09', 'RS10', 'RS11', 'RS12', 'RS36', 'RS44', 'RS45', 'RS47', 'RS77', 'RS80', 'RS90']
kmers = {s: Counter() for s in samples}
for s in samples:
    with gzip.open(f'/task/input/fastq/{s}.fastq.gz', 'rt') as f:
        for i, line in enumerate(f):
            if i % 4 == 1:
                seq = line.strip()
                for j in range(0, len(seq) - 24, 6):
                    kmers[s][seq[j:j+25]] += 1

all_kmers = set()
for s in samples:
    for k, v in kmers[s].items():
        if v >= 10:
            all_kmers.add(k)

print(f'Total candidates: {len(all_kmers)}')
mat = pd.DataFrame(index=list(all_kmers))
for s in samples:
    mat[s] = [kmers[s].get(k, 0) for k in mat.index]

# Binary presence/absence
bin_mat = (mat > 5).astype(int)
jaccard = bin_mat.corr()
print('Jaccard-like correlation of kmers:')
print(jaccard.round(3))
